const $=id=>document.getElementById(id);
const tiers=[{name:'Starter',low:400,high:700},{name:'Business',low:900,high:1800},{name:'Professional',low:2000,high:4000}];
const addons=[{id:'seo',name:'Expanded SEO',low:150,high:400},{id:'booking',name:'Booking integration',low:150,high:400},{id:'commerce',name:'E-commerce integration',low:400,high:1000}];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const range=(l,h)=>`${money(l)}–${money(h)}`;
function calculate(tier,pages,selected,rush){const t=tiers[tier];let low=t.low+pages*100,high=t.high+pages*200;for(const a of addons)if(selected.includes(a.id)){low+=a.low;high+=a.high}return {low:Math.ceil(low*(rush?1.2:1)),high:Math.ceil(high*(rush?1.35:1))}}
let estimateText='';
function update(){const t=tiers[+$('tier').value];const pages=Math.max(0,Math.min(30,Math.floor(+$('pages').value||0)));$('pages').value=pages;let selected=addons.filter(a=>$(a.id).checked);const rush=$('rush').checked;const result=calculate(+$('tier').value,pages,selected.map(a=>a.id),rush);const lines=[[t.name+' package',range(t.low,t.high)]];if(pages)lines.push([pages+' extra page'+(pages>1?'s':''),range(pages*100,pages*200)]);for(const a of selected)lines.push([a.name,range(a.low,a.high)+(a.id==='commerce'?'+':'')]);if(rush)lines.push(['Rush delivery','20–35%']);$('line-items').innerHTML=lines.map(([n,v])=>`<div class="row"><span>${n}</span><span>${v}</span></div>`).join('');$('total').textContent=range(result.low,result.high)+($('commerce').checked?'+':'');$('monthly').textContent=money(+$('care').value)+'/month';$('quote-note').textContent=$('commerce').checked?'E-commerce requires a custom scope; upper cost may exceed this range.':'USD · indicative range, subject to scope';const milestones=[[40,'To begin'],[30,'Design approval'],[30,'Before launch']];$('milestones').innerHTML=milestones.map(([n,label])=>`<div class="row"><span>${label} · ${n}%</span><span>${range(result.low*n/100,result.high*n/100)}</span></div>`).join('');$('seo-note').textContent=+$('tier').value===2?'Advanced SEO is included in Professional. Select expanded SEO only for additional work beyond the agreed package.':'Expanded SEO is additional to the agreed package scope.';estimateText='UG Web Development — Project estimate\n\n'+lines.map(l=>l.join(': ')).join('\n')+'\n\nOne-time estimate: '+$('total').textContent+' USD\nOngoing care: '+$('monthly').textContent+'\nPayment milestones: 40% initiation, 30% design approval, 30% before launch.\n\nIndicative range, not a binding quote. E-commerce may exceed the upper range. Taxes, domains, paid software and third-party subscriptions excluded. Final scope and rush availability require confirmation.';}
function download(text,name){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('estimate-form').addEventListener('input',update);$('estimate-form').addEventListener('submit',e=>e.preventDefault());document.querySelectorAll('[data-tier]').forEach(a=>a.addEventListener('click',()=>{$('tier').value=a.dataset.tier;update()}));$('download').addEventListener('click',()=>download(estimateText,'UG-project-estimate.txt'));
$('brief-form').addEventListener('submit',e=>{e.preventDefault();const body=`Name: ${$('name').value}\nEmail: ${$('email').value}\n\nProject: ${$('message').value}\n\n${estimateText}`;location.href='mailto:connor@vegas-underground.com?subject='+encodeURIComponent('Website project inquiry')+'&body='+encodeURIComponent(body);$('status').textContent='Your email app will open a draft. Review and send it to submit your inquiry.'});
const themeButton=$('theme');function applyTheme(dark){document.documentElement.dataset.theme=dark?'dark':'light';themeButton.textContent=dark?'☀ Light':'☾ Dark';themeButton.setAttribute('aria-pressed',String(dark))}let preference;try{preference=localStorage.getItem('ug-theme')}catch{}applyTheme(preference?preference==='dark':matchMedia('(prefers-color-scheme: dark)').matches);themeButton.addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';applyTheme(dark);try{localStorage.setItem('ug-theme',dark?'dark':'light')}catch{}});update();
